        volume: '音量：',
        aboutSongDescFull: '《南園・英雄之旅》是專為「英雄之旅@南園」創作的主題音樂。歌詞描繪了在蘭陽海岸的旅程中，透過感受孤獨、找回自己的英雄之旅。從龜山島到沙丘，從利澤到傳藝，每一步都是與昨日分離、走向更好的自己的過程。',
        aboutSongDescFull2: '這首音樂適合在進行任務時播放，營造海岸療癒氛圍，陪伴你走過每一段內在成長的旅程。',
        // index.html 頁面額外翻譯
        ariaLabelChooseMission: '英雄選擇',
