        voiceGuideMission5: '走上戏台，或站在台前。……想一想，你在生活里同时扮演几个角色？子女、父母、伴侣、主管、同事、朋友。……一个一个，在心里点名。……哪一个角色，让你最吃力？……哪一个角色，是你最像自己的时候？……如果今天可以暂时放下一个角色，你想放下哪一个？',
        mission5UserResponse: '請分享：你心中最重要的願望是什麼？這個願望對你來說意味著什麼？',
        mission5AIFeedbackCalm: '看清楚自己的角色，就能决定把力气放在哪里。',
        mission5AIFeedbackWorried: '角色多会累。写下一件可以请别人分担的事。',
        mission5AIFeedbackThinking: '那个最像自己的角色，值得多留一点时间给它。',
        mission6: '第六关　风檐・柔韧',
        mission6Loc: '📍 木构大地艺术｜隈研吾',
        mission6Title: '第六关　风檐・柔韧',
        mission6Subtitle: '📍 木构大地艺术｜隈研吾',
        mission6PageTitle: '第六关　风檐・柔韧',
        mission6PageIntro: '风檐是建筑师隈研吾在南园的木构大地艺术作品，一根根木条交错，撑起整个结构。这一关请你想一想，自己是靠什么撑过难关的。',
        mission6AIMessage: '準備好了嗎？點擊「開始引導」來開始這段內在旅程。',
        voiceGuideMission6: '走到风檐下，先听听风的声音。……抬头看木构的纹路。每一根木条都很细，交错之后，撑起了整个结构。……回想一段辛苦的日子，你是怎么过来的？……是谁陪着你？是什么习惯、哪一句话，让你没有断掉？……在心里，把他们一个一个叫出名字。',
