        mission7PageTitle: '第七关　孔雀亭・许诺',
        mission7PageIntro: '孔雀亭位在竹苑与兰苑之间。亭子是让人停下脚步的地方，这一关请你在亭中停一下，给未来的自己一个许诺。对游园旅人来说，这是今天的最后一关。',
        mission7AIMessage: '準備好了嗎？點擊「開始引導」來開始這段內在旅程。',
        voiceGuideMission7: '走进孔雀亭，找个位置坐下，或站一会儿。……回想今天走过的地方：你在榕树下放下了什么，在门前想跨过什么，在水边看见了什么。……现在，对一年后的自己说一句话。可以是一个承诺，也可以是一个提醒。……用一句话说完。……你可以按下录音，把这句话留给自己。',
