        mission8PageIntro: '水牛望月是雕刻家王秀杞的作品，位在住宿区。作品名称有两个画面：水牛是日复一日的耕作，月亮是远方的向往。这一关请你想一想，这两者在你身上怎么放在一起。',
        mission8AIMessage: '準備好了嗎？點擊「開始引導」來開始這段內在旅程。',
        voiceGuideMission8: '走到水牛望月前，绕着作品走一圈。……水牛一天一天下田，一步一步把田犁完。月亮在远处，摸不到，但每天晚上都在。……你的生活里，哪一件事是需要天天做的耕作？……哪一件，是你一直望着的月亮？……这两件事，有没有连在一起？',
        mission8UserResponse: '請分享：那是現在的你，還是過去的你？是什麼讓你感受到當下的真實？',
