        // 語音引導文字（英文）
        voiceGuideWave: 'Find a place to sit, or stand steady.……Take three deep breaths. Count to four as you breathe in, and to six as you breathe out.……Think of the one thing on your mind before you left today. It might be work, a person, or a decision you have not made.……You do not have to solve it. Just say its name in your mind.……Imagine setting it down under this banyan tree. When you have walked through Nanyuan, decide whether to come back for it.',
        waveAIFeedbackCalm: 'Give your attention to what you see next. That matter will wait under the tree.',
        waveAIFeedbackWorried: 'If you cannot set it down, writing its name is enough. Carry it on. Later stations may make it lighter.',
        waveAIFeedbackThinking: 'Write down what moved you just now, and read it again on the way back.',
        voiceGuideRain: 'Stand in front of the South Tower and look up, from the lowest eave to the highest.……Count the layers.……Each eave was built only after the one below it was finished.……Think of a goal in your heart. It does not have to be large.……If that goal is the top layer, which layer are you on now?……What must you finish first, to build the next layer?',
        rainUserResponse: 'Please share: What does this breeze remind you of? What forces in your life push you forward?',
        rainAIFeedbackCalm: 'Write the next layer in concrete terms. The more concrete it is, the easier it is to begin.',
        rainAIFeedbackWorried: 'A blurry goal is normal. First write one picture you long for.',
        rainAIFeedbackThinking: 'This longing is worth keeping. Later stations will use it.',
        voiceTimerEnd: 'Meditation time has ended. Thank you for giving yourself this time.',
