        aboutSong: '💡 About This Song',
        aboutSongDesc: 'A Rare Bond is the theme song of Hero Journey @ Nanyuan. The lyrics name Yingzi Gate, the Bamboo Court, the Orchid Court, the stage, the Wind Eaves, the South Tower, and Tongxin Hall.',
        aboutSongDesc2: 'On each station, Interact with Nature plays this song first.',
        musicTip: 'Headphones or a speaker are recommended.',
        lyrics: '📝 Lyrics',
        lyricsCredit: 'This song was co-created by Yu-Hsin Lin and AI on 2026/10/23',
        lyricsRights: '(A paid Suno subscription provides rights for personal, non-commercial use, and includes commercial use rights.)',
        lyricSec1: 'Verse 1',
        lyricSec2: 'Verse 2',
