        lyricSec4: 'Chorus',
        lyricSec5: 'Bridge',
        lyricSec6: 'Final chorus',
        lyricSec7: 'Outro',
        lyricsVerse1Line1: 'A guest comes to the veranda; a pot of tea stays warm, waiting to be poured',
        lyricsVerse1Line2: 'Yingzi Gate opens; osmanthus enters the garden before I do',
        lyricsVerse1Line3: 'Wind in the Bamboo Court writes the shadows into a scroll of small script',
        lyricsVerse1Line4: 'Ink in the Orchid Court is still wet; whose name falls at the paper\'s edge',
        lyricsChorus1Line1: 'Qinde Hall is deep; cypress scent hides among the painted colors',
        lyricsChorus1Line2: 'The stage song has ended; cicadas still circle through the afternoon',
        lyricsChorus1Line3: 'The Wind Eaves join the cypress and set the mountains before my eyes',
        lyricsChorus1Line4: 'Leaning on the South Tower rail, white clouds lend me half a day of ease',
        lyricsVerse2Line1: 'How long can a busy heart and body stay at ease',
        lyricsVerse2Line2: 'Better to watch the mountains from a high pavilion, and fish sky and water from a small boat',
        lyricsVerse2Line3: 'Nanyuan is a rare bond',
        lyricsVerse2Line4: 'Borrow the south pavilion awhile, and look out over the mountains',
        lyricsVerse3Line1: 'You sit quietly, and I look quietly',
        lyricsVerse3Line2: 'Do not ask when to return, and do not ask the passing years',
        lyricsVerse3Line3: 'The lamp of Tongxin Hall shines beside the moon gate',
        lyricsVerse3Line4: 'Nanyuan is a rare bond',
        lyricsChorus2Line1: 'Red brick and green moss both remember your face',
        lyricsChorus2Line2: 'Clear wind and a bright moon cost not a coin',
        lyricsChorus2Line3: 'The garden is embroidered in full; do not miss the spring',
        lyricsChorus2Line4: 'Nanyuan is a rare bond',
        lyricsVerse4Line1: 'Borrow the south pavilion awhile, and look out over the mountains',
        lyricsVerse4Line2: 'You sit quietly, and I look quietly',
        lyricsVerse4Line3: 'Do not ask when to return, and do not ask the passing years',
        lyricsVerse4Line4: 'The lamp of Tongxin Hall shines beside the moon gate',
        lyricsOutroLine1: 'Nanyuan, a rare bond',
        lyricsOutroLine2: 'Walk through it once, and it lives in the heart',
        lyricsOutroLine3: 'All four seasons are spring',
        lyricsOutroLine4: 'If we are bound, we meet again',
