        interactiveMap: 'Interactive Map',
        openGoogleMaps: 'Click the button below to open Google Maps and view the complete route',
        btnOpenGoogleMaps: '🧭 Open Google Maps',
        routeStep1Title: '🌊 Stage 1: Whispers in the Sea Breeze',
        routeStep1Location: '📍 Honeymoon Bay',
        routeStep1Desc: 'Sit by the sea at Honeymoon Bay in Toucheng, overlooking Turtle Island. Close your eyes and listen to the sound of the waves. Let AI guide you in a dialogue with your inner self.',
        routeStep2Title: '🌧 Stage 2: Mountain Breeze Brushing Face',
        routeStep2Location: '📍 Jiaoxi Cherry Blossom Cemetery',
        routeStep2Desc: 'Walking along the paths of Jiaoxi Cherry Blossom Cemetery, feel the mountain breeze gently brushing your cheeks and rustling through the treetops. AI will guide you to reflect: Where does this breeze come from? What forces in your life push you forward?',
        routeStep3Title: '🌅 Stage 3: Footprints in the Dunes',
        routeStep3Location: '📍 Sansuixi',
        routeStep3Desc: 'AI will guide you to walk slowly on the sand dunes near Sansuixi, observing the footprints you leave on the sand. These footprints represent your past experiences and symbolize that "footprints will eventually be erased by wind and sand"—can our past also be reunderstood and placed?',
        routeStep4Title: '🌍 Stage 4: Embrace of the Earth',
        routeStep4Location: '📍 Zhuangwei Sand Dune Ecological Park',
        routeStep4Desc: 'At Zhuangwei Sand Dune Ecological Park, travelers can sit on the sand dunes, touch the sand with their hands, and feel the temperature and texture of the sand. AI will guide you to reflect: How does the earth support us? Who in your life is your "earth"?',
        routeStep5Title: '⭐ Stage 5: Wishing under the Stars',
        routeStep5Location: '📍 Banyan Tree Park',
        routeStep5Desc: 'At Banyan Tree Park at night, travelers can lie in hammocks and gaze at the stars. AI will guide you through a one-minute silent meditation, after which you write down your wishes or aspirations.',
        routeStep6Title: '🌾 Stage 6: Voices in the Wind',
        routeStep6Location: '📍 Wushierjia Wetland',
        routeStep6Desc: 'At Wushierjia Wetland, travelers can cycle along paths, enjoying the scent of rice fields. AI will guide you: Do you hear the voices in the wind? How does this sound make you think of your own life?',
        routeStep7Title: '🍂 Stage 7: Pick up a Leaf',
        routeStep7Location: '📍 Traditional Arts Center',
        routeStep7Desc: 'On the paths at the Traditional Arts Center, travelers will be guided by AI to pick up a fallen leaf and reflect: This leaf was once part of a tree, now it\'s free. What do you need to let go of?',
        routeStep8Title: '🌊 Stage 8: Reflections in the River',
        routeStep8Location: '📍 Lizejian',
        routeStep8Desc: 'By the river in Lizejian, travelers will be guided by AI to observe their reflection and ponder: Is this the present you, or the past you? Travelers can photograph their reflection and record their feelings.',
        routeStep9Title: '🌊 Stage 9: Dancing with the Rhythm of Waves',
        routeStep9Location: '📍 Wuwei Harbor',
        routeStep9Desc: 'At Wuwei Harbor beach, travelers will be guided by AI to dance freely to the rhythm of the waves, experiencing the natural rhythm. Travelers can record their movements or feelings and save them.',
        routeStep10Title: '🌅 Stage 10: Farewell Ritual in Nature',
        routeStep10Location: '📍 Neipi Lover\'s Bay',
        routeStep10Desc: 'At Neipi Lover\'s Bay, this is the final stop of the journey. Travelers will be guided by AI to write their past worries and regrets on a leaf, then place it in the sea to be carried away by the waves. This symbolizes letting go of the past and embracing future freedom.',
        btnNavigate: '🧭 Navigate',
        btnStartTask: '🚀 Start Mission',
        // music-player.html page additional translations
        volume: 'Volume:',
        // hero-guide.js hero guide messages
        heroGreeting0: 'Hi, first time meeting. This coastline is long, you don\'t need to walk it all at once. As long as you\'re willing to take the first step, I\'ll be here with you all the way. Starting from Honeymoon Bay, we\'ll slowly try to hear ourselves.',
        heroGreeting1: 'Do you remember sitting down at Honeymoon Bay, letting the waves bring out the voice in your heart? That step was actually not simple. On the road ahead, I\'ll accompany you through Lanyang\'s wind and rain, practicing to steady your breath.',
        heroGreeting2: 'You\'ve already meditated at Honeymoon Bay and walked through Lanyang\'s drizzle. Compared to when you first started, you now know better how to walk with your emotions. Next stop, let\'s go to Lover\'s Bay together and watch a sunrise that belongs to you.',
        heroGreeting3: 'You\'ve walked all three coastlines: the whispers of Honeymoon Bay, Lanyang\'s wind and rain, and Lover\'s Bay\'s sunrise. Every time you come back to this line in the future, just close your eyes and you\'ll remember the courage you once walked with. I\'ll still be here, waiting for when you want to set out again.',
        heroGreetingDefault: 'You\'ve already left footprints on this Lanyang coast. No matter which stage you\'re at now, you can take some time to look back: along the way, you\'ve actually been growing into a new self.',
        heroFeedbackWave: 'Dear traveler, you were willing to sit down at Honeymoon Bay, listen to the waves and also listen to your own heart. This is already a rare courage. No matter how your heart fluctuates afterwards, remember: you once gave yourself such a quiet time. Next step, I\'ll accompany you in Lanyang\'s drizzle, practicing to stand firm even in wind and rain.',
        heroFeedbackRain: 'You just practiced breathing together with worry and fatigue in Lanyang\'s wind and rain. This shows you\'re not just facing the coastal scenery, but also willing to face yourself. When you\'re ready, let\'s go to Lover\'s Bay together and see what your heart will grow into when the sun slowly rises.',
        heroFeedbackDawn: 'Congratulations on walking through these three coastlines. From the whispers of Honeymoon Bay, to the settling in the drizzle, to the sunrise at Lover\'s Bay, you\'ve witnessed your own transformation step by step. This journey won\'t end just because the missions are complete. As long as you remember these moments, that courage will be awakened again, and I\'ll always remember the path you\'ve walked.',
        heroFeedbackDefault: 'You\'ve completed a mission that wasn\'t simple. Maybe you can\'t say clearly what this path has changed right now, but that\'s okay. Real changes will slowly emerge in daily life. I\'ll remember that you walked here today.',
