        subtitle: '蘭陽海岸・内面成長型三関ヒーロー旅',
        heroTitle: '内面成長型三関ヒーロー旅（蘭陽海岸）',
        heroDescription: 'ハネムーンベイから恋人湾までの海岸線に沿って、心拍と海風を同期させ、一歩一歩新しい自分を育てます。',
