        mission8PageIntro: '水牛望月は彫刻家・王秀杞の作品で、宿泊エリアにあります。題には二つの絵があります。水牛は日々の耕作、月は遠くの憧れ。この関では、その二つが自分の中でどう並ぶかを考えてください。',
        mission8AIMessage: '準備はできましたか？「音声ガイド開始」をクリックして、この内面の旅を始めましょう。',
        voiceGuideMission8: '水牛望月の前まで歩き、作品を一周してください。……水牛は一日一日田に出て、一歩一歩田を耕し終えます。月は遠く、触れられない。でも毎晩そこにあります。……あなたの生活で、毎日やる耕作はどれですか？……ずっと見ている月はどれですか？……この二つは、つながっていますか？',
        mission8UserResponse: '共有してください：それは今のあなたですか、それとも過去のあなたですか？何があなたに現在の瞬間の現実を感じさせますか？',
