        mission8AIFeedbackThinking: '見えたつながりを書いてください。それがあなたの答えです。',
        mission9Title: '第九関　同心楼・同心',
        mission9Subtitle: '📍 宿泊棟・夜',
        mission9PageTitle: '第九関　同心楼・同心',
        mission9PageIntro: '同心楼は宿泊エリアの主楼です。夜、部屋に戻る前、園が静かになってから行うのがよい。大切な人を思ってください。',
        mission9AIMessage: '準備はできましたか？「音声ガイド開始」をクリックして、この内面の旅を始めましょう。',
        voiceGuideMission9: '夜の南園は静かで、虫の声が聞こえます。……同心楼の前に立つか、部屋の窓辺に戻ってください。……今日、この旅を分かち合いたい人を一人。……その人は誰ですか？何を伝えたいですか？……もう一人、最近少し遠くなった人。二人のあいだに、まだ足りない一言は何ですか？……今夜メッセージを送らなくていい。先に心の中で一度言ってください。',
        mission9UserResponse: '共有してください：このリズムはあなたにどのような感情や考えをもたらしますか？',
