        mission10PageIntro: '快覧亭は湖辺にあります。朝、日帰り旅人が入る前の園は宿泊の人だけです。朝の湖辺で、日常へ持ち帰るものを整理してください。',
        mission10AIMessage: '準備はできましたか？「音声ガイド開始」をクリックして、この内面の旅を始めましょう。',
